create or replace function public.create_pos_transaction(_items jsonb, _paid numeric, _note text default null) returns jsonb language plpgsql security definer set search_path = public as $func$ declare _user uuid := auth.uid(); _tx_id uuid := gen_random_uuid(); _invoice text; _item jsonb; _pid uuid; _qty int; _prod record; _total numeric := 0; _cost numeric := 0; _subtotal numeric; begin if _user is null then raise exception 'Unauthorized'; end if; if _items is null or jsonb_array_length(_items) = 0 then raise exception 'Keranjang kosong'; end if; _invoice := 'INV-' || to_char(now(), 'YYYYMMDD-HH24MISS') || '-' || substr(replace(_tx_id::text,'-',''),1,4); insert into public.transactions (id, invoice_no, cashier_id, paid_amount, note) values (_tx_id, _invoice, _user, _paid, _note); for _item in select * from jsonb_array_elements(_items) loop _pid := (_item->>'product_id')::uuid; _qty := (_item->>'quantity')::int; if _qty <= 0 then raise exception 'Qty harus > 0'; end if; select id, name, sell_price, cost_price, stock into _prod from public.products where id = _pid for update; if not found then raise exception 'Produk tidak ditemukan'; end if; if _prod.stock < _qty then raise exception 'Stok tidak cukup'; end if; _subtotal := _prod.sell_price * _qty; _total := _total + _subtotal; _cost := _cost + (_prod.cost_price * _qty); insert into public.transaction_details (transaction_id, product_id, product_name, quantity, sell_price, cost_price, subtotal) values (_tx_id, _pid, _prod.name, _qty, _prod.sell_price, _prod.cost_price, _subtotal); update public.products set stock = stock - _qty where id = _pid; end loop; if _paid < _total then raise exception 'Pembayaran kurang'; end if; update public.transactions set total_amount = _total, total_cost = _cost, profit = _total - _cost, change_amount = _paid - _total where id = _tx_id; return jsonb_build_object('id', _tx_id, 'invoice_no', _invoice, 'total', _total, 'change', _paid - _total); end; $func$; grant execute on function public.create_pos_transaction(jsonb, numeric, text) to authenticated;